/* 05 task rows */
.tk-view{transition:opacity .3s ease}
.tk-view.hide{display:none}
.task{border-bottom:1px solid var(--line)}
.task:last-child{border-bottom:0}
.task-h{display:flex;align-items:center;gap:12px;padding:12px 16px}
.task-n{width:22px;height:22px;flex:none;display:grid;place-items:center;font-family:var(--mono);font-weight:700;font-size:11px;border:1px solid var(--icon-line);color:var(--muted);transition:border-color .35s,color .35s}
.task-n.ok{color:var(--success);border-color:rgba(62,207,142,.4)}
.task-h .tt{font-weight:600;font-size:14px}
.task-h .meta{margin-left:auto}
.sub-row{display:flex;align-items:center;gap:12px;padding:7px 16px 7px 50px;font-size:13px;color:var(--text-dim)}
.sub-row .sl{transition:color .35s ease}
.sub-row.done .sl{color:var(--text)}
.si{display:inline-grid;place-items:center;width:16px;height:16px;flex:none}
.si .ms{font-size:16px}
.sub-row .r{margin-left:auto}
.s-done{color:var(--success)}
.s-fail{color:var(--danger)}
.s-run{color:var(--accent)}
.s-wait{color:var(--muted)}
.pbar{height:2px;background:var(--line);margin:2px 16px 10px 50px;position:relative;overflow:hidden}
.pbar i{position:absolute;left:0;top:0;bottom:0;width:0;background:var(--accent);transition:width .2s linear}
.retry{font-family:var(--mono);font-size:10px;font-weight:700;text-transform:uppercase;color:var(--text);border:1px solid var(--line);padding:2px 6px;transition:border-color .25s,color .25s}
.retry:hover{border-color:var(--accent);color:var(--accent)}
.caps{display:flex;flex-wrap:wrap;gap:8px;padding:16px}
.cap{display:inline-flex;align-items:center;gap:8px;padding:6px 10px;border:1px solid var(--line);background:var(--card);font-size:13px;font-weight:600;transition:border-color .35s,background-color .35s,color .35s}
.cap.run{border-color:var(--accent);background-color:var(--accent-bg);color:var(--accent)}
.cap .si .ms{font-size:15px}

/* ---------- 05 task rows ---------- */
const tk = $('#tk');
const baseTasks = () => ([
  { t:'Research three competitors', meta:'3 sites', subs:[
    { l:'Read their pricing pages', r:'3/3', s:'done' },
    { l:'Compared plans and limits', r:'5 gaps', s:'done' }
  ]},
  { t:'Draft the launch email', meta:'2 versions', subs:[
    { l:'Pulled the new features', r:'Done', s:'run', p:0 },
    { l:'Wrote the subject lines', r:'Done', s:'wait' },
    { l:'Sent a test to the team', r:'Done', s:'fail' }
  ]},
  { t:'Update the help centre', meta:'2 articles', subs:[
    { l:'Billing questions', r:'draft', s:'wait' },
    { l:'Inviting your team', r:'draft', s:'wait' }
  ]}
]);
const stIcon = { done:['check_circle','s-done'], fail:['error','s-fail'], run:['graphic_eq','s-run'], wait:['description','s-wait'] };
let tasks, tkMode = 'list', listEl, capsEl, resetting = false;
function buildTk(){
  tasks = baseTasks();
  listEl = document.createElement('div'); listEl.className = 'tk-view';
  capsEl = document.createElement('div'); capsEl.className = 'tk-view caps';
  tasks.forEach((t, i) => {
    const task = document.createElement('div'); task.className = 'task';
    task.innerHTML = `<div class="task-h"><span class="task-n">${i+1}</span><span class="tt">${t.t}</span><span class="mono-xs meta fade-swap">${t.meta}</span></div>`;
    t.el = { n:task.querySelector('.task-n'), meta:task.querySelector('.meta'), ok:false };
    t.subs.forEach((s, j) => {
      const row = document.createElement('div');
      row.innerHTML = `<div class="sub-row"><span class="si"></span><span class="sl">${s.l}</span><span class="r mono-xs"></span></div><div class="unfold"><div class="uf"><div class="pbar"><i></i></div></div></div>`;
      const cap = document.createElement('span'); cap.className = 'cap';
      cap.innerHTML = `<span class="si"></span><span>${s.l}</span><span class="mono-xs accent cp"></span>`;
      s.el = { row:row.querySelector('.sub-row'), si:row.querySelector('.si'), r:row.querySelector('.r'), fold:row.querySelector('.unfold'), bar:row.querySelector('.pbar i'), cap, csi:cap.querySelector('.si'), cp:cap.querySelector('.cp'), t:i, j };
      task.appendChild(row); capsEl.appendChild(cap);
      paintSub(s, true);
    });
    listEl.appendChild(task); paintTask(t, true);
  });
  tk.innerHTML = ''; tk.append(listEl, capsEl); showMode(true);
}
function paintSub(s, first){
  if (s._s !== s.s){
    s._s = s.s;
    const [name, cls] = stIcon[s.s], anim = first ? '' : ' icon-in';
    s.el.si.innerHTML = ic(name, cls + anim); s.el.csi.innerHTML = ic(name, cls + anim);
    s.el.row.classList.toggle('done', s.s === 'done');
    s.el.cap.classList.toggle('run', s.s === 'run');
    s.el.fold.classList.toggle('open', s.s === 'run');
    s.el.r.classList.toggle('accent', s.s === 'run');
    if (s.s === 'fail') s.el.r.innerHTML = `<button class="retry" data-t="${s.el.t}" data-j="${s.el.j}">Retry</button>`;
    else if (s.s !== 'run') s.el.r.textContent = s.r;
    if (s.s !== 'run'){ s.el.cp.textContent = ''; s.el.bar.style.width = s.s === 'done' ? '100%' : '0%'; }
  }
  if (s.s === 'run'){ s.el.r.textContent = s.p + '%'; s.el.cp.textContent = s.p + '%'; s.el.bar.style.width = s.p + '%'; }
}
function paintTask(t, first){
  const ok = t.subs.every(s => s.s === 'done');
  if (ok !== t.el.ok){
    t.el.ok = ok; t.el.n.classList.toggle('ok', ok);
    t.el.n.innerHTML = ok ? ic('check', 'sm' + (first ? '' : ' icon-in')) : String(tasks.indexOf(t) + 1);
    first ? (t.el.meta.textContent = ok ? 'Completed' : t.meta) : swapText(t.el.meta, ok ? 'Completed' : t.meta);
    if (ok && !first) ambient('c5', 'done');
  }
}
function showMode(first){
  const change = () => { listEl.classList.toggle('hide', tkMode !== 'list'); capsEl.classList.toggle('hide', tkMode !== 'caps'); const v = tkMode === 'list' ? listEl : capsEl; if (!first){ v.classList.remove('enter'); v.offsetWidth; v.classList.add('enter'); } };
  first ? change() : morph(tk, change);
}
tk.addEventListener('click', e => {
  const b = e.target.closest('.retry'); if (!b) return;
  const s = tasks[+b.dataset.t].subs[+b.dataset.j];
  const busy = tasks.some(t => t.subs.some(x => x.s === 'run'));
  s.s = busy ? 'wait' : 'run'; s.p = 0; Sound.play('tab'); paintSub(s);
});
tabHandlers.tasks = v => { tkMode = v; showMode(); };
setInterval(() => {
  if (resetting) return;
  const all = tasks.flatMap(t => t.subs), run = all.find(s => s.s === 'run');
  if (run){
    run.p = Math.min(100, run.p + 2);
    if (run.p >= 100){
      run.s = 'done'; ambient('c5', 'pop');
      const nxt = all.find(s => s.s === 'wait'); if (nxt){ nxt.s = 'run'; nxt.p = 0; paintSub(nxt); }
    }
    paintSub(run); tasks.forEach(t => paintTask(t));
  } else if (all.every(s => s.s === 'done' || s.s === 'fail')){
    resetting = true;
    setTimeout(() => {
      tk.style.transition = 'opacity .35s ease'; tk.style.opacity = '0';
      setTimeout(() => { buildTk(); tk.style.opacity = '1'; resetting = false; }, 380);
    }, 2600);
  }
}, 110);
buildTk();
